51	using namespace llvm::support::endian;
52	using namespace lld;
53	using namespace lld::elf;
54	
55	static void printDefinedLocation(ELFSyncStream &s, const Symbol &sym) {
56	  s << "\n>>> defined in " << sym.file;
57	}
58	
59	// Construct a message in the following format.
60	//
61	// >>> defined in /home/alice/src/foo.o
62	// >>> referenced by bar.c:12 (/home/alice/src/bar.c:12)
63	// >>>               /home/alice/src/bar.o:(.text+0x1)
64	void elf::printLocation(ELFSyncStream &s, InputSectionBase &sec,
